    42	        }
    43	        if (request.guests() < 1) {
    44	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    45	        }
    46	        Room room = rooms.find(request.roomNumber())
    47	                .orElseThrow(() -> new HotelException(
    48	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    49	        if (request.guests() > room.capacity()) {
    50	            throw new HotelException(
    51	                    ErrorCode.CAPACITY_EXCEEDED,
    52	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    53	        }
