156	
157	import java.sql.Connection;
158	import java.sql.PreparedStatement;
159	import java.sql.ResultSet;
160	import java.sql.SQLException;
161	import java.util.ArrayList;
162	import java.util.List;
163	import javax.sql.DataSource;
164	
165	/** Every message the inn sent, so the front desk can check what each guest received. */
166	public final class SentMessages {
167	
168	    private final DataSource dataSource;
169	
170	    public SentMessages(DataSource dataSource) {
171	        this.dataSource = dataSource;
172	    }
173	
174	    Message add(String channel, String to, String subject, String body) {
175	        try (Connection connection = dataSource.getConnection();
176	                PreparedStatement insert = connection.prepareStatement(
177	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
178	            insert.setString(1, channel);
179	            insert.setString(2, to);
180	            insert.setString(3, subject);
181	            insert.setString(4, body);
182	            try (ResultSet generated = insert.executeQuery()) {
183	                generated.next();
184	                return new Message(generated.getLong("id"), channel, to, subject, body);
185	            }
186	        } catch (SQLException failure) {
187	            throw new IllegalStateException("could not keep the message to " + to, failure);
188	        }
189	    }
190	
191	    public List<Message> all() {
192	        try (Connection connection = dataSource.getConnection();
193	                PreparedStatement select = connection.prepareStatement(
194	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
195	                ResultSet rows = select.executeQuery()) {
196	            List<Message> messages = new ArrayList<>();
197	            while (rows.next()) {
198	                messages.add(new Message(
199	                        rows.getLong("id"),
200	                        rows.getString("channel"),
201	                        rows.getString("recipient"),
202	                        rows.getString("subject"),
203	                        rows.getString("body")));
204	            }
205	            return messages;
206	        } catch (SQLException failure) {
207	            throw new IllegalStateException("could not read the sent messages", failure);
208	        }
209	    }
210	}

